import { escHTML } from "@ntgovernment/squiz-factory/utils/xss";
import { containerModifiers } from "../_layouts/layoutProperties";

const CHEVRON_SVG =
  '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false"><path d="M7 10l5 5 5-5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

export default {
  async main(input = {}) {
    const { items = [], showToggleAll = false } = input;

    const publishedItems = items
      .map((item, sourceIndex) => ({ item, sourceIndex }))
      .filter(({ item }) => item && item.publishItem !== "No");
    const instanceId = Math.random().toString(36).slice(2, 8);

    const toggleAllHtml =
      showToggleAll && publishedItems.length > 0
        ? `<div class="accordion__header">
      <button type="button" class="accordion__toggle-all button button-tertiary" data-accordion-toggle-all>Open all</button>
    </div>`
        : "";

    const itemsHtml = publishedItems
      .map(({ item, sourceIndex }, index) => {
        const triggerId = `accordion-${instanceId}-trigger-${index}`;
        const panelId = `accordion-${instanceId}-panel-${index}`;
        const title = item && item.title ? item.title : "";
        const content = item && item.content ? item.content : "";

        return `
      <div class="accordion-item">
        <button id="${triggerId}" class="accordion-item__trigger" type="button" aria-expanded="false" aria-controls="${panelId}">
          <span class="accordion-item__title" data-sq-field="items[${sourceIndex}].title">${escHTML(title)}</span>
          <span class="accordion-item__icon" aria-hidden="true">${CHEVRON_SVG}</span>
        </button>
        <div id="${panelId}" class="accordion-item__panel" role="region" aria-labelledby="${triggerId}" hidden>
          <div class="accordion-item__content" data-sq-field="items[${sourceIndex}].content">${content}</div>
        </div>
      </div>`;
      })
      .join("");

    return /*html*/ `
<div data-component="accordion" ${containerModifiers(input)}>
  ${toggleAllHtml}
  <div class="accordion__items">
    ${itemsHtml}
  </div>
</div>
`;
  },
};
